/*
Supported lines:
  ORIGIN_DATA,....
  FRAME_DATA,....
  [EITKit] Sending Frame Data...
  other text is ignored

Usage:
1) Paste full serial output into RAW_SERIAL_LOG
2) Open browser console
3) It will print:
   - const ORIGIN_RAW = "..."
   - const FRAMES_RAW = [ ... ]
4) Copy the printed values and replace the hardcoded ones below
*/

function extractEITDataFromLog(rawText) {
  const lines = rawText
    .split(/\r?\n/)
    .map((s) => s.trim())
    .filter(Boolean);

  let originRaw = null;
  const framesRaw = [];

  for (const line of lines) {
    if (line.startsWith("ORIGIN_DATA,")) {
      originRaw = line.slice("ORIGIN_DATA,".length).trim();
      continue;
    }

    if (line.startsWith("FRAME_DATA,")) {
      framesRaw.push(line.slice("FRAME_DATA,".length).trim());
    }
  }

  return { originRaw, framesRaw };
}

const EXTRACTED_EIT = extractEITDataFromLog(RAW_SERIAL_LOG);

if (typeof window !== "undefined" && RAW_SERIAL_LOG.trim()) {
  console.log("const ORIGIN_RAW =", EXTRACTED_EIT.originRaw ? JSON.stringify(EXTRACTED_EIT.originRaw) + ";" : "null;");
  console.log("const FRAMES_RAW =", JSON.stringify(EXTRACTED_EIT.framesRaw, null, 2) + ";");
}

