// ─── PARSING ──────────────────────────────────────────────────────────────────
const parse = (s) => s.split(",").map(Number);

// Use extracted serial log if present, otherwise fallback
const ORIGIN_RAW =
  EXTRACTED_EIT.originRaw && EXTRACTED_EIT.originRaw.length > 0
    ? EXTRACTED_EIT.originRaw
    : ORIGIN_RAW_FALLBACK;

const FRAMES_RAW =
  EXTRACTED_EIT.framesRaw && EXTRACTED_EIT.framesRaw.length > 0
    ? EXTRACTED_EIT.framesRaw
    : FRAMES_RAW_FALLBACK;

const ORIGIN = parse(ORIGIN_RAW);
const FRAMES = FRAMES_RAW.map(parse);

// ─── EIT CONFIG ───────────────────────────────────────────────────────────────
const N = 8; // electrodes
const GRID = 96;

// Electrode positions on unit circle (top = electrode 0)
const EL = Array.from({ length: N }, (_, i) => ({
  x: Math.cos((2 * Math.PI * i) / N - Math.PI / 2),
  y: Math.sin((2 * Math.PI * i) / N - Math.PI / 2),
}));

// ─── RECONSTRUCTION ───────────────────────────────────────────────────────────
function reconstruct(deltaVec) {
  const img = new Float64Array(GRID * GRID);
  const wgt = new Float64Array(GRID * GRID);

  for (let row = 0; row < N; row++) {
    for (let col = 0; col < N; col++) {
      const dv = deltaVec[row * N + col];
      if (dv === 0) continue;

      // Injection electrodes (pair row → row+1)
      const eA = EL[row];
      const eB = EL[(row + 1) % N];
      // Measurement electrodes (pair col → col+1)
      const eC = EL[col];
      const eD = EL[(col + 1) % N];

      for (let py = 0; py < GRID; py++) {
        const ny = (py / (GRID - 1)) * 2 - 1;
        for (let px = 0; px < GRID; px++) {
          const nx = (px / (GRID - 1)) * 2 - 1;
          if (nx * nx + ny * ny > 0.97) continue;

          // Dipole sensitivity approximation
          const dAx = nx - eA.x, dAy = ny - eA.y;
          const dBx = nx - eB.x, dBy = ny - eB.y;
          const dCx = nx - eC.x, dCy = ny - eC.y;
          const dDx = nx - eD.x, dDy = ny - eD.y;

          const rA = Math.hypot(dAx, dAy) + 1e-9;
          const rB = Math.hypot(dBx, dBy) + 1e-9;
          const rC = Math.hypot(dCx, dCy) + 1e-9;
          const rD = Math.hypot(dDx, dDy) + 1e-9;

          // Injection field dot product
          const injDot = (dAx * dBx + dAy * dBy) / (rA * rA * rB * rB);
          // Measurement field dot product
          const msDot = (dCx * dDx + dCy * dDy) / (rC * rC * rD * rD);

          const s = injDot * msDot;
          const idx = py * GRID + px;
          img[idx] += s * dv;
          wgt[idx] += Math.abs(s);
        }
      }
    }
  }

  // Normalize
  for (let i = 0; i < GRID * GRID; i++) {
    if (wgt[i] > 1e-20) img[i] /= wgt[i];
  }
  return img;
}

// Average all frames
function avgFrames(frames) {
  const avg = new Float64Array(64);
  for (const f of frames) f.forEach((v, i) => (avg[i] += v));
  avg.forEach((_, i) => (avg[i] /= frames.length));
  return avg;
}

// Compute ΔV
function deltaV(frame, ref) {
  return frame.map((v, i) => v - ref[i]);
}

// ─── COLORMAP (Spectral-like: blue→cyan→green→yellow→red) ────────────────────
function colormap(t) {
  // t in [0,1]
  const stops = [
    [0.0, [48, 18, 59]],
    [0.15, [70, 90, 200]],
    [0.3, [20, 180, 220]],
    [0.5, [30, 220, 100]],
    [0.65, [220, 220, 30]],
    [0.82, [240, 100, 20]],
    [1.0, [200, 10, 10]],
  ];
  let lo = stops[0], hi = stops[stops.length - 1];
  for (let i = 0; i < stops.length - 1; i++) {
    if (t >= stops[i][0] && t <= stops[i + 1][0]) {
      lo = stops[i];
      hi = stops[i + 1];
      break;
    }
  }
  const f = (t - lo[0]) / (hi[0] - lo[0] + 1e-9);
  return lo[1].map((c, i) => Math.round(c + f * (hi[1][i] - c)));
}

// ─── RENDER IMAGE DATA ────────────────────────────────────────────────────────
function renderToImageData(pixelArr, scale = 4) {
  const size = GRID * scale;
  const buf = new Uint8ClampedArray(size * size * 4);

  // Find min/max for normalization (only inside circle)
  let mn = Infinity, mx = -Infinity;
  for (let py = 0; py < GRID; py++) {
    const ny = (py / (GRID - 1)) * 2 - 1;
    for (let px = 0; px < GRID; px++) {
      const nx = (px / (GRID - 1)) * 2 - 1;
      if (nx * nx + ny * ny > 0.97) continue;
      const v = pixelArr[py * GRID + px];
      if (v < mn) mn = v;
      if (v > mx) mx = v;
    }
  }
  const range = mx - mn || 1;

  for (let py = 0; py < GRID; py++) {
    const ny = (py / (GRID - 1)) * 2 - 1;
    for (let px = 0; px < GRID; px++) {
      const nx = (px / (GRID - 1)) * 2 - 1;
      const inCircle = nx * nx + ny * ny <= 0.97;

      const t = inCircle ? (pixelArr[py * GRID + px] - mn) / range : null;

      for (let sy = 0; sy < scale; sy++) {
        for (let sx = 0; sx < scale; sx++) {
          const idx = ((py * scale + sy) * size + px * scale + sx) * 4;
          if (!inCircle) {
            buf[idx] = buf[idx + 1] = buf[idx + 2] = 0;
            buf[idx + 3] = 0;
          } else {
            const [r, g, b] = colormap(t);
            buf[idx] = r;
            buf[idx + 1] = g;
            buf[idx + 2] = b;
            buf[idx + 3] = 255;
          }
        }
      }
    }
  }
  return { buf, size };
}

// ─── MAIN COMPONENT ───────────────────────────────────────────────────────────
export default function EITViewer() {
  const canvasRef = useRef(null);
  const [frameIdx, setFrameIdx] = useState(-1); // -1 = average
  const [scale] = useState(4);

  const getPixels = useCallback(() => {
    const ref = ORIGIN;
    const frame = frameIdx === -1 ? avgFrames(FRAMES) : FRAMES[frameIdx];
    const dv = deltaV(frame, ref);
    return reconstruct(dv);
  }, [frameIdx]);

  useEffect(() => {
    const pixels = getPixels();
    const { buf, size } = renderToImageData(pixels, scale);
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext("2d");
    const id = new ImageData(buf, size, size);
    ctx.putImageData(id, 0, 0);

    // Draw electrode markers
    const cx = size / 2, cy = size / 2, r = (size / 2) * 0.97;
    EL.forEach((e, i) => {
      const ex = cx + e.x * r;
      const ey = cy + e.y * r;
      ctx.beginPath();
      ctx.arc(ex, ey, 6, 0, 2 * Math.PI);
      ctx.fillStyle = "#ffffff";
      ctx.fill();
      ctx.strokeStyle = "#00e5ff";
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = "#00e5ff";
      ctx.font = "bold 11px monospace";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(i + 1, ex, ey);
    });

    // Draw circle outline
    ctx.beginPath();
    ctx.arc(cx, cy, r * (size / 2) / (size / 2), 0, 2 * Math.PI);
    ctx.strokeStyle = "rgba(0,229,255,0.3)";
    ctx.lineWidth = 1;
    ctx.stroke();
  }, [getPixels, scale]);

  // Stats
  const pixels = getPixels();
  const inCircle = [];
  for (let py = 0; py < GRID; py++) {
    const ny = (py / (GRID - 1)) * 2 - 1;
    for (let px = 0; px < GRID; px++) {
      const nx = (px / (GRID - 1)) * 2 - 1;
      if (nx * nx + ny * ny <= 0.97) inCircle.push(pixels[py * GRID + px]);
    }
  }
  const mn = Math.min(...inCircle);
  const mx = Math.max(...inCircle);
  const mean = inCircle.reduce((a, b) => a + b, 0) / inCircle.length;

  const activeFrame = frameIdx === -1 ? avgFrames(FRAMES) : FRAMES[frameIdx];
  const nonZeroVals = activeFrame.filter((v, i) => v !== 0 && ORIGIN[i] !== 0);
  const avgV = nonZeroVals.reduce((a, b) => a + b, 0) / nonZeroVals.length;

  return (
    <div
      style={{
        background: "#050a14",
        minHeight: "100vh",
        fontFamily: "'Courier New', monospace",
        color: "#c8d8e8",
        padding: "24px",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: "24px",
      }}
    >
      {/* Title */}
      <div style={{ textAlign: "center" }}>
        <div
          style={{
            fontSize: "11px",
            letterSpacing: "4px",
            color: "#00e5ff",
            textTransform: "uppercase",
            marginBottom: "4px",
          }}
        >
          Electrical Impedance Tomography
        </div>
        <div
          style={{
            fontSize: "22px",
            fontWeight: "bold",
            color: "#e8f4ff",
            letterSpacing: "1px",
          }}
        >
          EITKit — 8-Electrode Reconstruction
        </div>
        <div style={{ fontSize: "11px", color: "#4a7a99", marginTop: "4px" }}>
          Adjacent Drive · {FRAMES.length} frames · ΔV backprojection
        </div>
      </div>

      <div style={{ display: "flex", gap: "28px", flexWrap: "wrap", justifyContent: "center" }}>
        {/* Main image */}
        <div>
          <div
            style={{
              border: "1px solid #0a3550",
              borderRadius: "4px",
              background: "#030810",
              padding: "12px",
              position: "relative",
            }}
          >
            <div
              style={{
                fontSize: "10px",
                color: "#00e5ff",
                letterSpacing: "3px",
                marginBottom: "8px",
                textAlign: "center",
              }}
            >
              CONDUCTIVITY MAP
            </div>
            <canvas ref={canvasRef} style={{ display: "block", borderRadius: "2px" }} />
          </div>

          {/* Colorbar */}
          <div style={{ marginTop: "10px", display: "flex", alignItems: "center", gap: "8px" }}>
            <span style={{ fontSize: "10px", color: "#4a7a99", minWidth: "48px", textAlign: "right" }}>
              −ΔV
            </span>
            <div
              style={{
                flex: 1,
                height: "12px",
                background:
                  "linear-gradient(to right, rgb(48,18,59), rgb(70,90,200), rgb(20,180,220), rgb(30,220,100), rgb(220,220,30), rgb(240,100,20), rgb(200,10,10))",
                borderRadius: "2px",
                border: "1px solid #0a3550",
              }}
            />
            <span style={{ fontSize: "10px", color: "#4a7a99", minWidth: "48px" }}>+ΔV</span>
          </div>
        </div>

        {/* Right panel */}
        <div style={{ display: "flex", flexDirection: "column", gap: "16px", minWidth: "220px" }}>
          {/* Frame selector */}
          <div
            style={{
              background: "#030810",
              border: "1px solid #0a3550",
              borderRadius: "4px",
              padding: "14px",
            }}
          >
            <div style={{ fontSize: "10px", color: "#00e5ff", letterSpacing: "3px", marginBottom: "12px" }}>
              FRAME SELECT
            </div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: "4px", maxHeight: "160px", overflowY: "auto" }}>
              <button
                onClick={() => setFrameIdx(-1)}
                style={{
                  padding: "4px 8px",
                  fontSize: "10px",
                  background: frameIdx === -1 ? "#00e5ff" : "transparent",
                  color: frameIdx === -1 ? "#050a14" : "#4a7a99",
                  border: `1px solid ${frameIdx === -1 ? "#00e5ff" : "#0a3550"}`,
                  borderRadius: "2px",
                  cursor: "pointer",
                  fontFamily: "inherit",
                }}
              >
                AVG
              </button>
              {FRAMES.map((_, fi) => (
                <button
                  key={fi}
                  onClick={() => setFrameIdx(fi)}
                  style={{
                    padding: "4px 8px",
                    fontSize: "10px",
                    background: frameIdx === fi ? "#00e5ff" : "transparent",
                    color: frameIdx === fi ? "#050a14" : "#4a7a99",
                    border: `1px solid ${frameIdx === fi ? "#00e5ff" : "#0a3550"}`,
                    borderRadius: "2px",
                    cursor: "pointer",
                    fontFamily: "inherit",
                  }}
                >
                  {fi + 1}
                </button>
              ))}
            </div>
          </div>

          {/* Stats */}
          <div
            style={{
              background: "#030810",
              border: "1px solid #0a3550",
              borderRadius: "4px",
              padding: "14px",
            }}
          >
            <div style={{ fontSize: "10px", color: "#00e5ff", letterSpacing: "3px", marginBottom: "12px" }}>
              DIAGNOSTICS
            </div>
            {[
              ["Source", frameIdx === -1 ? "38-frame avg" : `Frame ${frameIdx + 1}`],
              ["Avg V meas", `${(avgV * 1000).toFixed(3)} mV`],
              ["ΔV min", `${(mn * 1e6).toFixed(2)} µV`],
              ["ΔV max", `${(mx * 1e6).toFixed(2)} µV`],
              ["ΔV mean", `${(mean * 1e6).toFixed(2)} µV`],
              ["Electrodes", "8 (adjacent)"],
              ["Meas/frame", "40 active"],
              ["Grid", `${GRID}×${GRID}`],
            ].map(([k, v]) => (
              <div
                key={k}
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  borderBottom: "1px solid #0a3550",
                  padding: "5px 0",
                  fontSize: "11px",
                }}
              >
                <span style={{ color: "#4a7a99" }}>{k}</span>
                <span style={{ color: "#c8d8e8" }}>{v}</span>
              </div>
            ))}
          </div>

          {/* Measurement matrix heatmap */}
          <div
            style={{
              background: "#030810",
              border: "1px solid #0a3550",
              borderRadius: "4px",
              padding: "14px",
            }}
          >
            <div style={{ fontSize: "10px", color: "#00e5ff", letterSpacing: "3px", marginBottom: "10px" }}>
              ΔV MATRIX (inject × meas)
            </div>
            <div style={{ display: "grid", gridTemplateColumns: `repeat(8, 1fr)`, gap: "2px" }}>
              {Array.from({ length: 8 }, (_, row) =>
                Array.from({ length: 8 }, (_, col) => {
                  const v = activeFrame[row * 8 + col] - ORIGIN[row * 8 + col];
                  const isZero = activeFrame[row * 8 + col] === 0;
                  const absMax = 0.0006;
                  const t = isZero ? null : Math.max(0, Math.min(1, (v + absMax) / (2 * absMax)));
                  const [r, g, b] = t !== null ? colormap(t) : [20, 20, 30];
                  return (
                    <div
                      key={`${row}-${col}`}
                      title={isZero ? "skipped" : `ΔV=${(v * 1e6).toFixed(1)}µV`}
                      style={{
                        width: "18px",
                        height: "18px",
                        background: `rgb(${r},${g},${b})`,
                        opacity: isZero ? 0.15 : 1,
                        borderRadius: "1px",
                      }}
                    />
                  );
                })
              )}
            </div>
            <div style={{ fontSize: "9px", color: "#2a4a5a", marginTop: "6px" }}>
              rows=inject pairs · cols=measure pairs
            </div>
          </div>
        </div>
      </div>

      {/* Footer */}
      <div style={{ fontSize: "9px", color: "#1a3550", letterSpacing: "2px", textAlign: "center" }}>
        EITKIT · SPI 500kHz · AD5930 · Adjacent-drive adjacent-measure protocol
      </div>
    </div>
  );
}